import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"The SMB Report Card - John Mulligan, IBM","description":"","frontmatter":{"title":"The SMB Report Card - John Mulligan, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","SMB","Storage","Linux","File System"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/The_SMB_Report_Card_-_John_Mulligan_IBM.md","filePath":"posts/2025/The_SMB_Report_Card_-_John_Mulligan_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2025/The_SMB_Report_Card_-_John_Mulligan_IBM.md"};function o(n,e,h,s,_,p){return t(),l("div",null,[...e[0]||(e[0]=[i('<p>John Mulligan（IBM）在会议上介绍了IBM团队在Ceph项目中集成SMB（Server Message Block）支持的最新进展。SMB是一种广泛用于Windows系统的文件共享协议，支持Windows、macOS和Linux。团队的主要目标是提供一个使用Ceph原生工具的SMB集成方案，并通过Ceph的orchestration层实现一致的部署和管理。</p><h3 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h3><ul><li><strong>SMB在Ceph中的集成</strong>：讨论了将SMB支持集成到Ceph中，特别是CephFS（Ceph File System），并提供与现有Ceph工具（如Cephadm）的无缝集成。</li><li><strong>现有工作与挑战</strong>：过去已有用户通过Samba在Ceph上运行SMB，但缺乏统一的文档和最佳实践。团队决定重新激活VFS CephFS模块，并与其他上游项目（如Samba和Kubernetes）合作，以改进SMB在Ceph中的集成。</li><li><strong>开发进展</strong>：开发了一个新的SMB管理模块，类似于现有的NFS模块，提供CLI命令和未来可能的Dashboard集成。支持Active Directory集成，并提供声明式和命令式两种管理方式。</li><li><strong>演示展示</strong>：John进行了一个演示，展示了如何在Ceph上创建SMB集群和共享，并通过Windows和Linux客户端进行访问。</li><li><strong>未来计划</strong>：短期计划包括添加Dashboard支持、优化性能和扩展Active Directory配置支持。长期计划包括支持并发SMB和NFS在同一子卷上运行、改进CephFS VFS模块等。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>团队将继续完善SMB在Ceph中的集成，特别是通过Cephadm的orchestration层提供更简化的管理体验。</li><li>未来将添加Dashboard支持，并优化性能以应对Samba的内存密集型操作。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>鼓励社区用户测试并反馈SMB集成功能，提交bug报告和功能请求。</li><li>团队将继续与Samba和Kubernetes等上游项目合作，改进Ceph的SMB支持。</li></ul><h3 id="相关标签" tabindex="-1">相关标签 <a class="header-anchor" href="#相关标签" aria-label="Permalink to &quot;相关标签&quot;">​</a></h3><ul><li>Ceph</li><li>SMB</li><li>Storage</li><li>Linux</li><li>File System</li></ul>',9)])])}const u=a(r,[["render",o]]);export{d as __pageData,u as default};
